style.css:
@-moz-document domain("gemini.google.com") {
/* Target the main content container that usually has max-width */
  mat-sidenav-content,
  .conversation-container, /* Add other potential selectors if needed */
  .chat-history { /* Target specific chat history element if width is constrained there */
    max-width: none !important; /* Remove the maximum width restriction */
    margin-left: 20px !important; /* Add some left margin/padding */
    margin-right: 20px !important; /* Add some right margin/padding */
    width: auto !important; /* Allow width to grow naturally */
  }

  /* Adjust specific inner elements if they also have width limits */
  .message-content { /* Example: If individual messages are constrained */
       max-width: none !important;
  }

  /* You might need to inspect the page and add/adjust selectors
     if the structure changes or if other elements limit width */
}
